/* What a step is: tag as on the wire (1 = ERASE, 2 = COPY, 3 = WRITE), a = block or dst, b = src or
* chunk length; hash is the one the step carries, data_at the offset of a WRITE's chunk in golden_*_written. */
typedef struct {
    uint8_t tag;
    uint32_t a;
    uint32_t b;
    uint8_t hash[8];
    uint32_t data_at;
} golden_step_t;

/* One manifest entry: tag 0 = hash, 1 = blank, 2 = unreadable. */
typedef struct {
    uint8_t tag;
    uint8_t hash[8];
} golden_entry_t;

